-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "DPS corpo a corpo"
L["rm.era.warrior.dps.Description"] = "Níveis 1–60, Armas e Fúria, e todo guerreiro fora da Postura de Defesa, também em reinos Hardcore e Autossuficientes; montada a partir do simulador, Icy Veins e Wowhead. Investida para puxar, Interceptar um alvo distante, Redemoinho (Trovoada antes de aprendê-lo) contra três ou mais inimigos lutando com você, depois Executar primeiro abaixo de 20%, Fender Armadura até cinco em chefes sem Expor Armadura, Sede de Sangue, Golpe Mortal, Batida logo após um golpe com Batida Aprimorada (ajustada para uma arma de duas mãos; altere isso duplicando a rotação), Redemoinho guardando raiva para seu golpe principal, Subjugar, Dilacerar até aprender seu golpe principal, Fender Armadura em alvos com bastante vida e Cortar Tendão perto do limite de raiva. Lembretes: Brado de Batalha, Golpe Heroico a partir de 40 de raiva (20 durante a evolução de nível), Cutilada em grupos de inimigos, Fúria Sanguinária, Golpes a Esmo, Desejo de Matar (chefes: nos seus últimos 30 segundos), Temeridade com Desejo de Matar, Murro ou Trombada com Escudo. Brado Intimidador e Retaliação vêm listados como desativados para emergências no Hardcore; a troca de posturas fica com você."
L["rm.era.warrior.protection.Name"] = "Tanque"
L["rm.era.warrior.protection.Description"] = "Escolhida sempre que você está na Postura de Defesa (Proteção, Fúria-Proteção ou tanque com arma de duas mãos); montada a partir da Icy Veins e do MaxDps. Contra quatro ou mais inimigos: Brado Desmoralizador e Brado de Batalha para gerar ameaça. Depois Revanche, Escudada, Sede de Sangue, Fender Armadura até cinco, Brado Desmoralizador em elites, Fender Armadura como preenchimento, e Dilacerar antes de Escudada ou Sede de Sangue. Escudada e Levantar Escudo só com um escudo equipado. Lembretes: Brado de Batalha, Levantar Escudo enquanto o alvo bate em você, Fúria Sanguinária, Golpe Heroico e Cutilada a partir de 50 de raiva, Trombada com Escudo, Último Recurso. Provocar, Muralha de Escudos e Desejo de Matar vêm listados como desativados; Postura de Batalha para Executar (a rotação integrada de DPS assume) e Brado Desafiador ficam com você."
L["rm.era.warrior.protection.icyveins.Name"] = "Tanque, ameaça com Brado de Batalha (Icy Veins)"
L["rm.era.warrior.protection.icyveins.Description"] = "O tanque “sem Fender” da Icy Veins para grupos em que quatro ou mais jogadores ouvem seu brado (Brado de Batalha da Fase 5 em diante), uma alternativa à rotação integrada de tanque recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Brado Desmoralizador mantido, Revanche, Escudada ou Sede de Sangue, depois Brado de Batalha como preenchimento de ameaça em vez de Fender Armadura; Escudada e Levantar Escudo só com um escudo equipado. Os mesmos lembretes do tanque recomendado; volte a Fender Armadura ao focar um alvo em meio a vários."
L["rm.forever.warrior.dps.Name"] = "Armas e Fúria (Icy Veins)"
L["rm.forever.warrior.dps.Description"] = "Armas e Fúria corpo a corpo do nível 1 ao 60, e o padrão para qualquer guerreiro fora da Postura de Defesa. No Forever a raiva é escassa e fica oculta dos addons, então ela é acumulada, gastando em qualquer outra coisa só enquanto Golpe Mortal ou Sede de Sangue está recuperando: Investida para puxar, Ímpeto da Vitória, Interceptar, Executar (dentro do alcance) em elites, chefes ou em grupo, Redemoinho ou Trovoada, Brado Desmoralizador e Batida contra grupos de inimigos, Golpe Lanceador em Gigantes e Dracônicos, Dilacerar até ter Sede de Sangue, Subjugar, Golpe Mortal, Sede de Sangue, depois Redemoinho, Batida enquanto parado e dois Fender Armadura (cinco em elites). Lembretes: Brado de Batalha, Fúria Sanguinária, a interrupção, Golpe Heroico enquanto o golpe principal se recupera, Cutilada em grupos de inimigos, Golpes a Esmo, Desejo de Matar e Raiva Incontrolada; Temeridade e Retaliação estão listadas, mas desativadas. Fica com você: troca de posturas, Cortar Tendão e consumíveis."
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "Armas e Fúria, gastar raiva (Warcraft Tavern)"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "A lista da Warcraft Tavern para gastar sempre, em grupos e raides: cinco Fender Armadura primeiro, Executar acima de tudo abaixo de 20%, Subjugar, Dilacerar até ter Sede de Sangue, Golpe Mortal, Sede de Sangue, Redemoinho, Golpe Lanceador sempre que sair do tempo de recarga, Batida depois de pegar Batida Aprimorada; Golpe Heroico ou Cutilada sempre que você puder pagar por eles (a raiva fica oculta no Forever, então não há limite de 60 de raiva nem Cortar Tendão com raiva de sobra), Temeridade sempre que sair do tempo de recarga junto com Desejo de Matar. Escolha esta em vez da rotação integrada da Icy Veins se você joga em grupos e não precisa guardar raiva entre as puxadas. Uma alternativa à rotação integrada de DPS corpo a corpo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.forever.warrior.protection.Name"] = "Proteção (Icy Veins)"
L["rm.forever.warrior.protection.Description"] = "Tanque sempre que você estiver em Postura de Defesa, do nível 10 ao 60. Puxa com Investida (em Postura de Defesa depois que você tiver Vanguarda), Ímpeto da Vitória e, contra dois ou mais inimigos, Trovoada sempre que sair do tempo de recarga, Brado Desmoralizador, Escudada, Revanche e Dilacerar. Contra um alvo: Escudada, Revanche, Brado Desmoralizador, Dilacerar, Fender Armadura (cinco em elites) e Trovoada em alvos perigosos. Lembretes: Brado de Batalha, Fúria Sanguinária, Trombada com Escudo, Levantar Escudo enquanto você segura o alvo, Golpe Heroico enquanto Escudada e Revanche estão ambas recuperando, Cutilada em grupos de inimigos; Provocar e Muralha de Escudos estão listados, mas desativados. A raiva, a vida e a mana do alvo ficam ocultas dos addons no Forever, então os limites de raiva, os lançadores e Último Recurso são decisões suas. Fica com você: trocar para Postura de Batalha para usar Investida antes de Vanguarda, provocar outros inimigos e pegar os que escaparem."
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "Proteção, manutenção de penalidades (Warcraft Tavern)"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "A ordem de tanque da Warcraft Tavern: Trovoada, Brado Desmoralizador e cinco Fender Armadura mantidos em cada alvo primeiro, depois Revanche, Dilacerar e Escudada por último, com Golpe Heroico ou Cutilada sempre que você puder pagar por eles (a raiva fica oculta no Forever, então não há limite de 60 de raiva). Sem Levantar Escudo nem lembretes defensivos. Escolha esta em vez da rotação integrada de tanque da Icy Veins se você prefere manter as penalidades primeiro. Uma alternativa à rotação integrada de Proteção recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.mop.warrior.arms.Name"] = "Recomendada"
L["rm.mop.warrior.arms.Description"] = "Recomendada para Armas do nível 10 ao 90, escolhida na especialização Armas. Investida para abrir, e de novo para gerar raiva quando você se afasta. Golpe Colossal sempre que estiver ausente ou prestes a acabar, Golpe Mortal, Seta Tempestuosa na janela do Golpe Colossal, Rugido do Dragão e Tornado de Aço fora dela. Abaixo de 20% de vida: Executar na janela, com 100 de raiva ou para manter Execução Repentina, Subjugar com Apetite por Sangue. Senão, Batida na janela, Subjugar com quatro acúmulos, Batida com 100 de raiva, Subjugar, Batida. Dois ou mais inimigos lutando com você acrescentam Golpes a Esmo, Trovoada para Feridas Profundas, Tornado de Aço e Rugido do Dragão. Ímpeto da Vitória abaixo de 70% de vida; Brado de Batalha para gerar raiva. Lembretes: um brado quando nenhum estiver ativo, Postura de Batalha, Raiva Incontrolada, Temeridade, Avatar e Banho de Sangue com Golpe Colossal em lutas longas, Estandarte da Caveira, Golpe Heroico ou Cutilada com raiva de sobra, Salto Heroico na janela, Murro, Morte pela Espada e Regeneração Enfurecida com pouca vida. Arremesso Estilhaçante vem listado, mas desativado. Fica com você: cancelar Tornado de Aço, a troca de posturas e o posicionamento."
L["rm.mop.warrior.arms.icyveins.Name"] = "Acumular para Golpe Colossal (Icy Veins)"
L["rm.mop.warrior.arms.icyveins.Description"] = "Desativada por padrão. A ordem de Armas da Icy Veins e da Wowhead: fora da janela de Golpe Colossal, usa Subjugar e Batida só acima de 80 de raiva, guardando raiva para a janela em vez de usar Batida como preenchimento. Na janela: Golpe Mortal, Batida, Subjugar, Arremesso Heroico. Abaixo de 20% de vida: Golpe Colossal, Golpe Mortal, Executar, Subjugar, Rugido do Dragão. Golpes a Esmo contra dois inimigos, uma lista de Trovoada para grupos contra três ou mais. Golpe Heroico ou Cutilada só perto do limite de raiva. Os mesmos lembretes da rotação integrada recomendada de Armas. Ative esta e desative aquela para usá-la."
L["rm.mop.warrior.fury.Name"] = "Recomendada"
L["rm.mop.warrior.fury.Description"] = "Recomendada para Fúria do nível 10 ao 90, escolhida na especialização Fúria. Investida para abrir e para gerar raiva. Golpe Colossal assim que duas cargas de Golpe Furioso estiverem guardadas (uma com Temeridade), Golpe Furioso quando a janela estiver se fechando, Sede de Sangue, Golpe Colossal, Seta Tempestuosa, Rugido do Dragão fora da janela, Executar aqui com Fúria Obcecada (armas de uma mão), Tornado de Aço enquanto Sede de Sangue recarrega, com Punhos de Titã (armas de duas mãos) mais um Golpe Furioso fora da janela, Executar, Golpe Selvagem com Onda de Sangue, Golpe Furioso guardando uma carga para a próxima janela, Golpe Selvagem, Arremesso Heroico, Brado de Batalha para gerar raiva. Dois ou mais inimigos lutando com você acrescentam Tornado de Aço, Rugido do Dragão, Redemoinho para Cutelo de Carne e Golpes Furiosos em área. Lembretes: um brado quando nenhum estiver ativo, Postura de Batalha, Raiva Incontrolada para Enfurecer, Temeridade, Avatar e Banho de Sangue com Golpe Colossal em lutas longas, Estandarte da Caveira, Golpe Heroico ou Cutilada com raiva de sobra, Salto Heroico, Murro e defesas com pouca vida. Fica com você: cancelar Tornado de Aço."
L["rm.mop.warrior.fury.icyveins.Name"] = "Recargas dentro do Golpe Colossal (Icy Veins)"
L["rm.mop.warrior.fury.icyveins.Description"] = "Desativada por padrão. A ordem de Fúria da Icy Veins gasta Tornado de Aço ou Rugido do Dragão primeiro dentro da janela de Golpe Colossal, e põe Executar à frente de Sede de Sangue abaixo de 20% de vida. Fora da janela: Golpe Colossal, Sede de Sangue, Golpe Furioso só com duas cargas, Golpe Selvagem com Onda de Sangue, brado, Golpe Selvagem. Quatro ou mais inimigos: Sede de Sangue para Enfurecer, Redemoinho até três acúmulos de Cutelo de Carne, Golpe Furioso. Golpe Heroico ou Cutilada só perto do limite de raiva. Os mesmos lembretes da rotação integrada recomendada de Fúria. Ative esta e desative aquela para usá-la."
L["rm.mop.warrior.protection.Name"] = "Recomendada"
L["rm.mop.warrior.protection.Description"] = "Tanque do nível 10 ao 90, escolhida na especialização Proteção. Investida ou Arremesso Heroico para puxar. Devastar para manter três Armadura Enfraquecida em elites e chefes, Rugido do Dragão, Tornado de Aço, Onda de Choque contra três inimigos e Trovoada assim que sair do tempo de recarga contra três ou mais. Depois Revanche para a raiva que falta para um Levantar Escudo, Escudada, Revanche com Defender a Linha, Devastar para Feridas Profundas, Ímpeto da Vitória abaixo de 60% de vida, Revanche, Trovoada para Golpes Enfraquecidos, Executar, Seta Tempestuosa, um brado para gerar raiva e Devastar (Fender Armadura antes do nível 26). Lembretes: Postura de Defesa, um brado quando nenhum estiver ativo, Levantar Escudo sempre que estiver inativo, Barreira de Escudos quando ferido com raiva de sobra, Golpe Heroico ou Cutilada com Ultimato, Estímulo ou perto do limite, Brado Desmoralizador, Raiva Incontrolada, Regeneração Enfurecida, Último Recurso e Muralha de Escudos com pouca vida, seus tempos de recarga ofensivos, Murro. Provocar e Salto Heroico vêm listados, mas desativados. Fica com você: quem provocar, e Levantar Escudo versus Barreira de Escudos contra magia."
L["rm.mop.warrior.unspecialized.Name"] = "Sem especialização"
L["rm.mop.warrior.unspecialized.Description"] = "Para os níveis 1 a 9, ou até você escolher uma especialização. Investida para puxar, Ímpeto da Vitória, Executar e Golpe Heroico quando você tiver 30 de raiva; lembra você de entrar na Postura de Batalha se não estiver em nenhuma postura."
L["rm.retail.warrior.arms.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.warrior.arms.Description"] = "Recomendada para Armas no Midnight. Em combate, o jogo agora oculta raiva, Dilacerar, Golpe Colossal, ativações, tempos de recarga e vida para addons, então esta rotação mostra a própria sugestão do Assistente de Combate da Blizzard (a rotação de um botão), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: Golpe Heroico (um botão essencial que a sugestão nunca usa), Avatar e Lança do Campeão em combate, Brado de Batalha entre os combates, Murro em um lançamento interrompível (só acende onde o jogo permite ler o lançamento), Morte pela Espada sempre que estiver pronta em combate (a vida fica oculta no Retail, então decidir quando usá-la é com você)."
L["rm.retail.warrior.arms.colossus.Name"] = "Referência de Colosso (SimulationCraft)"
L["rm.retail.warrior.arms.colossus.Description"] = "Apenas referência, desativada por padrão: a ordem Colosso do SimulationCraft e da Icy Veins acumula Poder Colossal com Golpe Mortal e lê bônus que o Midnight oculta em combate. Investida para abrir; Golpes a Esmo contra dois ou mais; Golpe Mortal abaixo de cinco acúmulos de Poder Colossal; Dilacerar antes de Golpe Colossal; Assolador; Executar com dois acúmulos de Morte Súbita; Golpe Colossal; Lança do Campeão; Demolir durante Golpe Colossal com Poder Colossal; Golpe Heroico; Golpe Mortal; Executar; Subjugar; Dilacerar abaixo de 5 segundos; Tornado de Aço contra dois ou mais; Batida. Lembretes: Avatar, Morte pela Espada, Brado de Batalha, Murro."
L["rm.retail.warrior.arms.slayer.Name"] = "Referência de Matador (SimulationCraft)"
L["rm.retail.warrior.arms.slayer.Description"] = "Apenas referência, desativada por padrão: a ordem Matador do SimulationCraft, da Icy Veins e da Wowhead lê raiva, Dilacerar, Golpe Colossal, Morte Súbita e Oportunista, que o Midnight oculta em combate. Investida para abrir; Golpes a Esmo contra dois ou mais inimigos em combate; Dilacerar antes de Golpe Colossal quando Dilacerar estiver acabando; Assolador logo antes de Golpe Colossal; Executar com dois acúmulos de Morte Súbita; Golpe Colossal; Tornado de Aço durante Golpe Colossal ou Avatar; Golpe Heroico; Subjugar com dois acúmulos de Oportunista; Golpe Mortal; Executar; Subjugar; Dilacerar abaixo de 5 segundos; Batida. Lembretes: Avatar com Golpe Colossal pronto, Morte pela Espada, Brado de Batalha, Murro."
L["rm.retail.warrior.fury.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.warrior.fury.Description"] = "Recomendada para Fúria no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard (Alvoroço, Sede de Sangue, Golpe Furioso, Executar, Fúria de Odyn e Tornado de Aço), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: Temeridade, Avatar e Lança do Campeão em combate, Brado de Batalha entre os combates, Murro, Regeneração Enfurecida sempre que estiver pronta em combate (a vida fica oculta no Retail, então decidir quando usá-la é com você)."
L["rm.retail.warrior.fury.slayer.Name"] = "Referência de Matador (SimulationCraft)"
L["rm.retail.warrior.fury.slayer.Description"] = "Apenas referência, desativada por padrão: a ordem Matador do SimulationCraft lê Enfurecer, Temeridade e Morte Súbita, que o Midnight oculta em combate; a raiva fica oculta no Retail, então Alvoroço espera apenas pelo próprio custo. Investida para abrir; Redemoinho pelo bônus contra dois ou mais inimigos em combate; Alvoroço quando Enfurecer estiver acabando; durante Temeridade, Alvoroço, Tornado de Aço, Executar com Morte Súbita, Fúria de Odyn; Golpe Triturante; Banho de Sangue; Executar; Fúria de Odyn; Golpe Furioso; Alvoroço; Sede de Sangue; Redemoinho. Lembretes: Temeridade, Avatar, Regeneração Enfurecida, Brado de Batalha, Murro."
L["rm.retail.warrior.fury.thane.Name"] = "Referência de Thane da Montanha (Icy Veins)"
L["rm.retail.warrior.fury.thane.Description"] = "Apenas referência, desativada por padrão: a ordem Thane da Montanha do SimulationCraft e da Icy Veins intercala Impacto Trovejante e lê bônus que o Midnight oculta em combate. Investida para abrir; Redemoinho pelo bônus contra dois ou mais; Alvoroço quando Enfurecer estiver ausente ou acabando (a raiva fica oculta no Retail, então não há Alvoroço com 100 de raiva); Banho de Sangue durante Temeridade; Impacto Trovejante com dois acúmulos; Golpe Triturante; Banho de Sangue; Alvoroço durante Temeridade; Impacto Trovejante durante Avatar; Golpe Furioso; Impacto Trovejante; Alvoroço; Sede de Sangue; Executar; Fúria de Odyn; Trovoada; Redemoinho. Os mesmos lembretes da referência Matador."
L["rm.retail.warrior.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.warrior.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Guerreiro). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Guerreiro compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.warrior.protection.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.warrior.protection.Description"] = "Recomendada para Proteção no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard para seu dano e ameaça, e para enquanto você lança ou não tem um inimigo como alvo. A sugestão nunca lança Levantar Escudo nem Ignorar Dor, então os dois são lembretes sempre que puderem ser usados e seu alvo estiver atacando você; o jogo oculta a raiva, então Ignorar Dor vai acender com mais frequência do que você precisa. Outros lembretes: Avatar, Brado Desmoralizador e Lança do Campeão em combate, Muralha de Escudos e Último Recurso sempre que estiverem prontos em combate (a vida fica oculta no Retail, então decidir quando usá-los é com você), Provocar em grupo quando seu alvo atacar outra pessoa, Brado de Batalha entre os combates, Murro."
L["rm.retail.warrior.protection.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.warrior.protection.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft lê Levantar Escudo, Impacto Trovejante e Poder Colossal, que o Midnight oculta em combate; a raiva e a vida ficam ocultas no Retail. Investida para abrir; Assolador; Impacto Trovejante com dois acúmulos; Demolir com cinco acúmulos de Poder Colossal; Investida com Escudo; Impacto Trovejante; Escudada; Trovoada; Executar; Revanche; Devastar. Lembretes: Levantar Escudo quando seu bônus não estiver ativo e você estiver tanqueando, Ignorar Dor, Avatar, Brado Desmoralizador, Lança do Campeão, Muralha de Escudos e Último Recurso sempre que estiverem prontos em combate, Brado de Batalha, Murro."
L["rm.sod.warrior.dps.Name"] = "DPS corpo a corpo (SoD)"
L["rm.sod.warrior.dps.Description"] = "Temporada da Descoberta, níveis 1–60 com as runas conforme você as grava: arma de duas mãos, duas armas, Gladiador e evolução de nível, e todo guerreiro da Temporada da Descoberta fora da Postura de Defesa; montada a partir do simulador Fase 6 e Wowhead Fase 7/8. Investida, Ímpeto da Vitória, Interceptar, Redemoinho (Trovoada antes dele) contra dois ou mais inimigos, Batida com três acúmulos de Batidão, Dilacerar mantido, Batida com Rebentação de Sangue (assim que sair do tempo de recarga com Tempo Preciso gravado), Sede de Sangue, Golpe Mortal, Escudada (com um escudo), Subjugar; depois Golpe Rápido quando estiver gravado (arma de duas mãos), senão Redemoinho, Golpe Furioso e Devastar (Fender Armadura antes dele); Executar com 30 de raiva ou com Morte Súbita; Cortar Tendão perto do limite de raiva. Lembretes: Brado de Batalha e Brado de Comando, Golpe Heroico a partir de 50 de raiva (sempre enquanto Consumido pela Raiva enfurecer você), Cutilada, Fúria Sanguinária, Alvoroço, Desejo de Matar, Temeridade, Golpes a Esmo, interrupções. Raiva Incontrolada e a passagem rápida pela Postura de Batalha para Apetite por Sangue vêm listadas como desativadas."
L["rm.sod.warrior.dps.icyveins.Name"] = "DPS corpo a corpo (SoD, Icy Veins)"
L["rm.sod.warrior.dps.icyveins.Description"] = "As páginas de Fúria e Armas da Temporada da Descoberta da Icy Veins, uma alternativa à rotação integrada de DPS corpo a corpo da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Executar no topo da prioridade abaixo de 20% ou com Morte Súbita, Batida com Rebentação de Sangue, Sede de Sangue ou Golpe Mortal, Redemoinho, Subjugar, Golpe Furioso, depois Golpe Rápido e Cortar Tendão só acima de 60 de raiva; sem Dilacerar; Golpe Heroico só acima de 80 de raiva. Os mesmos lembretes da rotação integrada recomendada."
L["rm.sod.warrior.dps.wowhead.Name"] = "Troca de posturas com Preditor de Batalhas (SoD, Wowhead)"
L["rm.sod.warrior.dps.wowhead.Description"] = "A rotação da Fase 7/8 da Wowhead para Alma do Preditor de Batalhas ou o conjunto de seis peças do Tier 1 (que o Rotation Master não consegue ver), uma alternativa à rotação integrada de DPS corpo a corpo da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Troca de posturas para manter os bônus de predição ativos, Golpe Heroico quase sempre, depois Sede de Sangue, Batida com Rebentação de Sangue, Redemoinho, Golpe Furioso e Cortar Tendão; sem Dilacerar e sem Subjugar. Confira o momento das trocas no jogo antes de confiar nela."
L["rm.sod.warrior.tank.Name"] = "Tanque (SoD)"
L["rm.sod.warrior.tank.Description"] = "Tanque da Temporada da Descoberta, escolhida na Postura de Defesa; montada a partir da Wowhead Fase 8 e do simulador. Investida; contra dois ou mais inimigos, Trovoada, Onda de Choque, Escudada, Revanche, Redemoinho e Devastar; depois Escudada sempre que Determinação do Defensor estiver ausente ou acabando, Revanche, Escudada, Onda de Choque, Executar, Redemoinho com cinco acúmulos de Astúcia do Gladiador, Devastar (Fender Armadura antes dele), Brado Desmoralizador e Trovoada em elites, Dilacerar antes de Escudada; Escudada e Levantar Escudo só com um escudo equipado. Lembretes: Brado de Batalha e Brado de Comando, Levantar Escudo, Golpe Heroico a partir de 50 de raiva, Cutilada a partir de 55, Fúria Sanguinária, Alvoroço, Último Recurso, interrupções. Provocar, Muralha de Escudos, Desejo de Matar, Temeridade e Retaliação vêm listados como desativados; a troca para Gladiador para Executar fica com você."
L["rm.tbc.warrior.dps.icyveins.Name"] = "DPS corpo a corpo (Icy Veins)"
L["rm.tbc.warrior.dps.icyveins.Description"] = "Níveis 1–70, Armas ou Fúria, seguindo a Icy Veins. A mesma puxada, lembretes e passos de evolução de nível da versão simulador, mas com Golpe Mortal o Executar vem primeiro, com Sede de Sangue o Executar vem logo depois dela, Redemoinho segue sem guardar raiva e Cortar Tendão só com a raiva quase cheia. O momento da Batida, a troca de posturas e Raiva Incontrolada ficam com você. Uma alternativa à rotação integrada de DPS corpo a corpo do simulador recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.tbc.warrior.dps.simulator.Name"] = "DPS corpo a corpo (simulador)"
L["rm.tbc.warrior.dps.simulator.Description"] = "Níveis 1–70, Armas ou Fúria. Puxa com Investida, depois Ímpeto da Vitória, Interceptar, Desordem e Redemoinho quando dois ou mais inimigos lutam com você (Trovoada antes de aprendê-lo). Com Sede de Sangue ou Golpe Mortal: esse golpe, Redemoinho com raiva de sobra, Executar, Subjugar. Antes deles: Redemoinho, Executar, Subjugar, Dilacerar. A raiva de sobra vai para Devastar ou Fender Armadura, depois Cortar Tendão. Lembra você de Brado de Batalha, Fúria Sanguinária, Golpe Heroico ou Cutilada para gastar raiva, Golpes a Esmo, Desejo de Matar, Temeridade e interrupções. O momento da Batida, a troca de posturas e Raiva Incontrolada ficam com você."
L["rm.tbc.warrior.protection.icyveins.Name"] = "Tanque (Icy Veins)"
L["rm.tbc.warrior.protection.icyveins.Description"] = "Níveis 10–70, escolhida enquanto você está em Postura de Defesa, seguindo a Icy Veins. Escudada, Revanche, depois Devastar ou Fender Armadura, com Dilacerar no início da luta até aprender Escudada. Em grupos de inimigos: Trovoada, e Brado Desmoralizador contra elites. Levantar Escudo é lembrado sempre que seu alvo está atacando você e você carrega um escudo. Provocações e outras utilidades ficam com você. Uma alternativa à rotação integrada de tanque da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.tbc.warrior.protection.wowhead.Name"] = "Tanque (Wowhead)"
L["rm.tbc.warrior.protection.wowhead.Description"] = "Níveis 10–70, escolhida enquanto você está em Postura de Defesa. Escudada, Revanche, Trovoada e Brado Desmoralizador mantidos em elites e chefes, depois Devastar ou Fender Armadura. Em grupos de inimigos: Trovoada e Brado Desmoralizador primeiro. Lembra você de Levantar Escudo (com um escudo equipado) contra chefes e inimigos de nível mais alto, Golpe Heroico ou Cutilada, Brado de Batalha, Fúria Sanguinária, Trombada com Escudo e, em emergências, Último Recurso e Muralha de Escudos. Provocações e outras utilidades ficam com você."
